// DOM/media controls only. Frame scheduling and every GPU operation live in Rust/WASM.
// @ts-ignore generated by wasm-pack
import init, { VideoPipeline } from './wasm/pkg/burn_yolo_inference.js';
// @ts-ignore generated by wasm-pack
import wasmUrl from './wasm/pkg/burn_yolo_inference_bg.wasm?url';
import './video.css';
const video = document.querySelector<HTMLVideoElement>('#source')!;
const canvas = document.querySelector<HTMLCanvasElement>('#output')!;
const status = document.querySelector<HTMLElement>('#status')!;
const camera = document.querySelector<HTMLButtonElement>('#camera')!;
const stopButton = document.querySelector<HTMLButtonElement>('#stop')!;
const file = document.querySelector<HTMLInputElement>('#file')!;
const confidence = document.querySelector<HTMLInputElement>('#confidence')!;
const iou = document.querySelector<HTMLInputElement>('#iou')!;
let ready: Promise<unknown> | undefined;
let session: VideoPipeline | undefined;
let stream: MediaStream | undefined;
let objectUrl: string | undefined;
let poll: ReturnType<typeof setInterval> | undefined;
let generation = 0;
let latest: unknown;
function stop() {
  generation++;
  clearInterval(poll);
  if (session) { session.stop(); session.free(); session = undefined; }
  video.pause(); video.srcObject = null; video.removeAttribute('src'); video.load();
  stream?.getTracks().forEach(track => track.stop()); stream = undefined;
  if (objectUrl) URL.revokeObjectURL(objectUrl);
  objectUrl = undefined;
  stopButton.disabled = true;
  camera.disabled = file.disabled = false;
}
function thresholds() {
  try { session?.thresholds(Number(confidence.value), Number(iou.value)); }
  catch (error) { status.textContent = String(error); }
}
async function start(localFile?: File) {
  stop();
  const token = generation;
  camera.disabled = file.disabled = true;
  stopButton.disabled = false;
  status.textContent = 'Loading WASM/model and initializing the shared WebGPU device…';
  try {
    ready ??= init({ module_or_path: wasmUrl });
    await ready;
    if (token !== generation) return;
    if (localFile) { objectUrl = URL.createObjectURL(localFile); video.src = objectUrl; }
    else {
      const next = await navigator.mediaDevices.getUserMedia({ video: { width: { ideal: 640 }, height: { ideal: 480 }, facingMode: 'environment' }, audio: false });
      if (token !== generation) { next.getTracks().forEach(t=>t.stop()); return; }
      stream = next; video.srcObject = stream;
    }
    await video.play();
    if (token !== generation) return;
    const next = await VideoPipeline.create(canvas, video);
    if (token !== generation) { next.free(); return; }
    session = next;
    thresholds();
    session.start();
    status.textContent = 'Running. Waiting for first inference and shader compilation…';
    poll = setInterval(() => {
      if (!session) return;
      try {
        const metrics = session.metrics();
        latest = { mode: 'Rust GPU video', userAgent: navigator.userAgent, ...metrics,
          notes: 'Host submission timings, not GPU timestamps. One inference in flight; busy frames are skipped. First three frames are excluded from host timing means. No application pixel/prediction readback in the frame loop.' };
        status.textContent = JSON.stringify(latest, null, 2);
        if (metrics.error) stop();
      } catch (error) { stop(); status.textContent = String(error); }
    }, 500);
  } catch (error) { if (token === generation) { stop(); status.textContent = String(error); } }
}
camera.onclick = () => void start();
file.onchange = () => { const selected = file.files?.[0]; if (selected) void start(selected); };
stopButton.onclick = () => { stop(); status.textContent = 'Stopped. Media tracks released.'; };
confidence.onchange = iou.onchange = thresholds;
document.querySelector<HTMLButtonElement>('#download')!.onclick = () => {
  if (!latest) return;
  const url = URL.createObjectURL(new Blob([JSON.stringify(latest,null,2)], { type:'application/json' }));
  const a = document.createElement('a'); a.href=url; a.download='yolo-gpu-video.json'; a.click();
  setTimeout(()=>URL.revokeObjectURL(url),1000);
};
window.addEventListener('pagehide',stop);

document.querySelector<HTMLButtonElement>('#validate')!.onclick = async () => {
  if (!session) return;
  const current = session;
  clearInterval(poll);
  current.stop();
  video.pause();
  const token = generation;
  status.textContent = 'Waiting for the pending frame, then reading back diagnostic data…';
  try {
    while (current.metrics().inFlight) {
      await new Promise(resolve => setTimeout(resolve, 20));
      if (token !== generation) return;
    }
    const report = await current.validate_last_frame();
    if (token !== generation) return;
    const { input, head, ...summary } = report;
    latest = { ...summary, metrics: current.metrics(), diagnosticReadbacks: true,
      notes: 'Explicit stopped-frame validation. GPU detections compared with CPU decode/NMS of the same head. Model accuracy versus PyTorch is a separate check.' };
    status.textContent = JSON.stringify(latest, null, 2);
  } catch (error) { if (token === generation) status.textContent = String(error); }
};
